"""Build the local concept/runtime comparison gallery from captured PNGs."""
from pathlib import Path
from html import escape
OUT=Path(__file__).resolve().parents[2]/'art/review/terrain_fidelity/2026-10-12/island_art_direction'
views=[('default','Whole island'),('distant','From afar'),('rim_upper_front','Rim and turf'),('pond_shore','Pond shore'),('underside','Lower stone'),('underside_bottom','Bottom face')]
options=''.join(f'<option value="{key}">{label}</option>' for key,label in views)
full=[f'orbit_{y}' for y in [-164,-104,-44,16,76,136]]+[f'low_orbit_{y}' for y in [-120,-60,0,60,120,180]]
orbits=''.join(f'<a href="final_{v}.png" target="_blank"><img loading="lazy" src="final_{v}.png" alt="{escape(v)}"><span>{escape(v.replace("_"," "))}</span></a>' for v in full)
studies=[('crags','Broad shoulders','Rejected: bevel ring and toothy lower edge.'),('clusters','Hanging clusters','Rejected: too many individual teeth.'),('ledge','Thin ledge','Rejected: an artificial belt above the base.'),('material','Stronger mineral detail','Reduced: too gritty from afar.'),('after','Deeper inward roots','Revised after orbit review: crowded rear plates.'),('rounded','Continuous lower stone','Retained: upper fractures settle into one bottom.'),('softcore','Smooth lower surface','Rejected: plaster-like surface.'),('turf','Denser turf clusters','Rejected: a decorative fringe instead of natural patches.')]
cards=''.join(f'<article><a href="{tag}_default.png" target="_blank"><img loading="lazy" src="{tag}_default.png" alt="{name}"></a><h3>{name}</h3><p>{note}</p></article>' for tag,name,note in studies)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>云露村 · Floating island lookdev</title>
<style>*{box-sizing:border-box}body{margin:0;background:#171c18;color:#e9e4d5;font:16px/1.6 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:30px}h1{font-size:38px;margin:.3em 0}h2{margin-top:48px;font-size:24px}p{max-width:940px;color:#bebeb0}a{color:#e4d5a0}button,select{font:inherit;padding:9px 14px;border:1px solid #5c6554;border-radius:6px;background:#293226;color:inherit}label{display:inline-flex;align-items:center;gap:12px;margin:8px 20px 8px 0}input{width:220px}img{max-width:100%;display:block}figure{margin:0}#compare{position:relative;aspect-ratio:1671/941;overflow:hidden;border-radius:10px;background:#242a22}#compare img{width:100%;height:100%;position:absolute;inset:0}#before{clip-path:inset(0 50% 0 0)}#divider{position:absolute;top:0;bottom:0;left:50%;border-left:2px solid #fff9;pointer-events:none}.labels{display:flex;justify-content:space-between;margin:10px 2px;color:#e1d8b5}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.grid a{text-decoration:none}.grid img{border-radius:6px}.grid span{display:block;padding:6px}.studies{grid-template-columns:repeat(4,1fr)}article{background:#252c24;border-radius:8px;overflow:hidden}article h3,article p{margin:10px 14px}article h3{font-size:17px}article p{font-size:14px}summary{cursor:pointer;font-size:20px;margin:20px 0}footer{padding:40px 0;color:#a0a796;font-size:14px}@media(max-width:850px){main{padding:16px}.grid,.studies{grid-template-columns:repeat(2,1fr)}h1{font-size:28px}}</style>
<main><div style="color:#bdc7a9;letter-spacing:.15em">GODOT · ART DIRECTION</div><h1>云露村 · A quieter floating island</h1><p>Broad fractured rim stones, physical turf patches, mineral and grass detail maps, and side rock that turns into one calm bottom. The authored island and ponds remain editable.</p>
<details><summary>Concept reference</summary><img src="concept.png" alt="User supplied concept reference"><p>Concept art, not an engine screenshot. It guides the finish and atmosphere.</p></details>
<h2>Before / retained result</h2><label>View <select id="view">OPTIONS</select></label><label>Compare <input id="split" aria-label="Before and after split" type="range" min="0" max="100" value="50"></label><div class="labels"><span>Before · ff4db69</span><span>Retained · actual Godot render</span></div><figure id="compare"><img id="current" src="final_default.png" alt="Retained island"><img id="before" src="before_default.png" alt="Before island"><div id="divider"></div></figure><p>Move the slider to compare matched cameras. <a id="full" href="final_default.png" target="_blank">Open retained image at full size</a>.</p>
<h2>Material close views</h2><div class="grid"><a href="final_stone_material.png" target="_blank"><img src="final_stone_material.png" alt="Stone material close view"></a><a href="final_ground_material.png" target="_blank"><img src="final_ground_material.png" alt="Ground material close view"></a></div><h2>All sides, including below</h2><div class="grid">ORBITS</div>
<h2>Decisions behind the retained version</h2><div class="grid studies">STUDIES</div>
<h2>Acceptance notes</h2><p>There is no continuous grey lip band or painted green shoulder. The rim greenery is supported geometry; grey breaks through locally. Stone spans vary without tiny terminal slivers. Lower plates were removed from the turning face after the rear orbit exposed crowding.</p><p>The bottom is a single closed shallow surface. Some angular transitions remain visible from extreme low cameras; the result does not claim the concept’s hand-composed richness or beauty parity. Stone and ground use two tileable 1024² packed material maps with mipmaps. Ground detail retains its flattening control for future trampling.</p><p><a href="review.md">Review and verification record</a> · <a href="tests-final.json">Fresh test results</a></p><footer>All runtime views: Godot 4.7.2, Forward+, Apple M4 Pro, 1671 × 941. Target-device performance and owner art approval are separate. Water is animated; matched shots are not frame-identical.</footer></main>
<script>const view=document.querySelector('#view'),split=document.querySelector('#split'),before=document.querySelector('#before'),current=document.querySelector('#current'),divider=document.querySelector('#divider');function update(){before.src='before_'+view.value+'.png';current.src='final_'+view.value+'.png';document.querySelector('#full').href=current.src}view.addEventListener('change',update);split.addEventListener('input',()=>{before.style.clipPath='inset(0 '+(100-split.value)+'% 0 0)';divider.style.left=split.value+'%'});</script></html>'''
